// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address _owner) public {
        vm.assume(_owner != address(0));
        vm.assume(_owner != address(this));
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        (bool callSuccess, bytes memory retData) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, _owner));
        assertTrue(callSuccess, "call reverted");
        bool returnedSuccess = abi.decode(retData, (bool));
        assertTrue(returnedSuccess, "setOwner must return true on success");
    }
}
